// Regenerate src/domain/holidays-cn.ts from holiday-cn (Chinese public
// holidays). Usage: node scripts/update-holidays.mjs [year ...]
// Without arguments it refreshes the years already in the generated file.
// The download is untrusted data: it is only JSON.parsed and strictly checked,
// and any surprise fails the run instead of writing a partial file.
import { existsSync, readFileSync, writeFileSync } from 'node:fs'

const OUTPUT = new URL('../src/domain/holidays-cn.ts', import.meta.url)
const SOURCE = 'https://github.com/NateScarlet/holiday-cn'
const RAW = 'https://raw.githubusercontent.com/NateScarlet/holiday-cn/master'
const DATE = /^\d{4}-\d{2}-\d{2}$/

function fail(message) {
  console.error(`update-holidays: ${message}`)
  process.exit(1)
}

function defaultYears() {
  if (existsSync(OUTPUT)) {
    const match = /CN_HOLIDAY_YEARS: readonly number\[\] = \[([\d, ]*)\]/.exec(readFileSync(OUTPUT, 'utf8'))
    const years = match?.[1].split(',').map(part => part.trim()).filter(Boolean).map(Number) ?? []
    if (years.length > 0) return years
  }
  return [2026, 2027]
}

const args = process.argv.slice(2)
for (const arg of args) if (!/^\d{4}$/.test(arg)) fail(`not a year: ${arg}`)
const years = [...new Set(args.length > 0 ? args.map(Number) : defaultYears())].sort((a, b) => a - b)

/** Weekday (Mon–Fri) off days of one year file, validated strictly. */
function weekdayOffDays(year, data) {
  if (typeof data !== 'object' || data === null || Array.isArray(data)) fail(`${year}: not an object`)
  if (data.year !== year) fail(`${year}: file says year ${JSON.stringify(data.year)}`)
  if (!Array.isArray(data.papers) || !data.papers.every(paper => typeof paper === 'string')) fail(`${year}: bad papers`)
  if (!Array.isArray(data.days)) fail(`${year}: days is not an array`)
  const result = []
  for (const day of data.days) {
    if (typeof day !== 'object' || day === null) fail(`${year}: bad day entry`)
    if (typeof day.name !== 'string') fail(`${year}: bad name ${JSON.stringify(day.name)}`)
    if (typeof day.date !== 'string' || !DATE.test(day.date)) fail(`${year}: bad date ${JSON.stringify(day.date)}`)
    if (typeof day.isOffDay !== 'boolean') fail(`${year}: bad isOffDay for ${day.date}`)
    const [y, m, d] = day.date.split('-').map(Number)
    const instant = new Date(Date.UTC(y, m - 1, d))
    if (instant.getUTCFullYear() !== y || instant.getUTCMonth() !== m - 1 || instant.getUTCDate() !== d) {
      fail(`${year}: impossible date ${day.date}`)
    }
    if (y !== year) fail(`${year}: date ${day.date} is outside the year`)
    // Make-up workdays (isOffDay false) fall on weekends, which are off-peak anyway.
    const weekday = instant.getUTCDay()
    if (day.isOffDay && weekday >= 1 && weekday <= 5) result.push(day.date)
  }
  return result
}

const all = new Set()
for (const year of years) {
  const url = `${RAW}/${year}.json`
  const response = await fetch(url)
  if (!response.ok) fail(`${url}: HTTP ${response.status}`)
  let data
  try {
    data = JSON.parse(await response.text())
  } catch {
    fail(`${url}: not JSON`)
  }
  const days = weekdayOffDays(year, data)
  for (const date of days) all.add(date)
  console.log(`${year}: ${days.length} weekday holidays`)
}

const dates = [...all].sort()
const text = `/**
 * GENERATED by scripts/update-holidays.mjs (\`pnpm run holidays:update\`). Do not edit by hand.
 *
 * Chinese public holidays that fall on Monday–Friday, from holiday-cn:
 * ${SOURCE} (${RAW}/<year>.json)
 * Copyright (c) 2019 NateScarlet. Licensed under the MIT License.
 *
 * Make-up workdays are omitted: they fall on weekends, which are off-peak anyway.
 */

/** Years this list covers (sorted). */
export const CN_HOLIDAY_YEARS: readonly number[] = [${years.join(', ')}]

/** Weekday public holidays as Beijing dates 'YYYY-MM-DD' (sorted). */
export const CN_WEEKDAY_OFF_DAYS: readonly string[] = [
${dates.map(date => `  '${date}',`).join('\n')}
]
`
writeFileSync(OUTPUT, text)
console.log(`wrote ${dates.length} dates for ${years.join(', ')}`)
